+				 */
+				spin_unlock(&ci->lock);
+				nr_reclaim = __try_to_reclaim_swap(
+						xswap_rmap_to_entry(swp_tb),
+						TTRS_ANYWAY);
+				spin_lock(&ci->lock);
+				if (nr_reclaim) {
+					offset += abs(nr_reclaim);
+					continue;
+				}
+#endif
 			}
 			offset++;
 		}
